import pandas as pd, numpy as np
from sklearn.model_selection import KFold
import lightgbm as lgb
df = pd.read_csv('data.csv')
Xdf = pd.get_dummies(df[['log_hist_days','region','log_pre_gmv','orders','cat_share','tenure','tier']],
                     columns=['region','tier'], drop_first=True).astype(float)
X=Xdf.values; D=df['D'].values; y=df.dY.values
def run(seed):
    kf=KFold(5,shuffle=True,random_state=seed); ry=np.zeros(len(y)); rd=np.zeros(len(D))
    for tr,te in kf.split(X):
        mk=lambda: lgb.LGBMRegressor(n_estimators=400,learning_rate=0.05,subsample=0.8,colsample_bytree=0.8,verbose=-1,random_state=seed)
        ry[te]=y[te]-mk().fit(X[tr],y[tr]).predict(X[te]); rd[te]=D[te]-mk().fit(X[tr],D[tr]).predict(X[te])
    return ry,rd
ests=[]; cate={k:[] for k in ['tier0','tier1','tier2','tier3','D<9','D>=9','gmvQ1','gmvQ4']}
for seed in range(10):
    ry,rd=run(seed)
    th=np.sum(rd*ry)/np.sum(rd*rd); ests.append(th)
    gq=pd.qcut(df.log_pre_gmv,4,labels=False).values
    masks={'tier0':df.tier.values==0,'tier1':df.tier.values==1,'tier2':df.tier.values==2,'tier3':df.tier.values==3,
           'D<9':D<9,'D>=9':D>=9,'gmvQ1':gq==0,'gmvQ4':gq==3}
    for k,m in masks.items():
        cate[k].append(np.sum(rd[m]*ry[m])/np.sum(rd[m]**2))
print('ATE 跨10个随机种子: mean=%.4f  sd=%.4f  range=[%.4f,%.4f]'%(np.mean(ests),np.std(ests),min(ests),max(ests)))
ry,rd=run(0)
def se_of(m):
    th=np.sum(rd[m]*ry[m])/np.sum(rd[m]**2); e=rd[m]*(ry[m]-th*rd[m])
    return np.sqrt(np.sum(e**2))/np.sum(rd[m]**2)
gq=pd.qcut(df.log_pre_gmv,4,labels=False).values
masks={'tier0':df.tier.values==0,'tier1':df.tier.values==1,'tier2':df.tier.values==2,'tier3':df.tier.values==3,
       'D<9':D<9,'D>=9':D>=9,'gmvQ1':gq==0,'gmvQ4':gq==3}
print('\n分组 CATE (跨种子均值 ± 解析se):')
for k in masks:
    print(f'  {k:7s} n={masks[k].sum():5d}  {np.mean(cate[k]):+.4f} (se {se_of(masks[k]):.4f})  种子间sd={np.std(cate[k]):.4f}')
